  async function doImport() {
    if (!org) { toast('No organisation found.'); return; }
    setLoading(true); setLoadingMsg('Preparing…');
    try {
      // Collect unique payee names from suggestions
      const payeeIds = {};
      const uniquePayeeNames = [...new Set(
        selectedRows.map(t => autoCatMap[t._key]?.sugPayee).filter(Boolean)
      )];
      // Check existing payees, batch-create new ones in parallel
      const newPayeeNames2 = uniquePayeeNames.filter(
        name => !(payees||[]).find(p => p.name.toLowerCase() === name.toLowerCase())
      );
      // Assign existing payee IDs
      uniquePayeeNames.forEach(name => {
        const existing = (payees||[]).find(p => p.name.toLowerCase() === name.toLowerCase());
        if (existing) payeeIds[name] = existing.id;
      });
      // Create new payees in parallel
      if (newPayeeNames2.length > 0) {
        const created = await Promise.all(
          newPayeeNames2.map((name, i) => {
            const col = (PALETTE||[])[i % (PALETTE||['#888']).length] || '#888';
            return upsertPayee(org.id, name, col);
          })
        );
        created.forEach((p, i) => {
          payeeIds[newPayeeNames2[i]] = p.id;
          setPayees(prev => prev.find(x => x.id === p.id) ? prev : [...prev, p]);
        });
      }

      const toImport = selectedRows.map(t => {
        const sug = autoCatMap[t._key];
        // Only apply category if it came from an explicit rule (not merchant intelligence guess)
        // fromIntel=true means it's a UI suggestion only — user must approve it in Transactions view
        const applyCat = sug?.sugCat && !sug?.fromIntel ? sug.sugCat : (t.cat || null);
        // Only apply payee if suggestion came from a rule
        const applyPayee = sug?.sugPayee && !sug?.fromIntel ? sug.sugPayee : '';
        const payeeName = applyPayee;
        return ({
          date:        t.date,
          desc:        t.desc,
          amt:         t.amt,
          cat:         applyCat,
          payee_id:    payeeName ? payeeIds[payeeName] || null : null,
          note:        t.note,
          account_id:  selectedAccount || null,
        });
      });
      if (toImport.length === 0) { toast('No transactions selected.'); return; }
      setLoadingMsg(`Importing ${toImport.length} transaction${toImport.length!==1?'s':''}…`);
      const { inserted, linked, skipped } = await bulkImportTransactions(org.id, toImport);
      const parts = [`Imported ${inserted} transaction${inserted!==1?'s':''}`];
      if (linked)  parts.push(`${linked} existing linked to account`);
      if (skipped) parts.push(`${skipped} duplicates skipped`);

      // Detect new payees from rules
      const newPayeeNames = new Set();
      toImport.forEach(t => {
        const matchedRule = (rules||[]).find(r => t.desc?.toLowerCase().includes(r.keyword?.toLowerCase()) && r.payee);
        if (matchedRule?.payee) {
          const existing = (payees||[]).find(p => p.name.toLowerCase() === matchedRule.payee.toLowerCase());
          if (!existing) newPayeeNames.add(matchedRule.payee);
        }
      });
      if (newPayeeNames.size > 0) setNewPayeesFound([...newPayeeNames]);

      // Update bank account opening balance from earliest imported statement
      if (selectedAccount) {
        const summaries = parsedFiles.map(pf => pf.summary).filter(
          s => s && s.openingBalance != null && s.periodStart
        );
        if (summaries.length > 0) {
          const earliest = summaries.reduce((best, s) =>
            !best || s.periodStart < best.periodStart ? s : best, null
          );
          try {
            const acct = (accounts||[]).find(a => a.id === selectedAccount);
            if (acct && earliest && (!acct.opening_date || earliest.periodStart < acct.opening_date)) {
              const updated = await updateBankAccount(selectedAccount, {
                opening_balance: earliest.openingBalance,
                opening_date:    earliest.periodStart,
              });
              if (updated && setAccounts) {
                setAccounts(prev => prev.map(a => a.id===selectedAccount ? {...a,...updated} : a));
              }
              parts.push(`Opening balance updated to $${Math.abs(earliest.openingBalance).toFixed(2)}`);
            }
          } catch(e) { console.warn('Opening balance update failed:', e.message); }
        }
      }

      toast(parts.join(' ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â· ') + '.');

      const fresh = await getTransactions(org.id, '2000-01-01', '2099-12-31');
      const normalise = t => ({ ...t, cat:t.category_id??null, desc:t.description??'', amt:parseFloat(t.amount)??0, payee:t.payees?.name??t.payee??'', note:t.note??'' });
      setTxns(fresh.map(normalise));

      // Save intel suggestions to DB so they persist after navigation
      const intelSugs = Object.values(autoCatMap).filter(s => s.fromIntel && s.sugCat);
      if (intelSugs.length > 0) {
        // Map _key back to the actual inserted transaction id — best effort
        savePendingSuggestions(org.id, intelSugs.map(s => ({
          ...s,
          txnId: s.txnId, // _key format, DB function handles gracefully
        }))).catch(e => console.warn('savePendingSuggestions failed:', e.message));
      }

      // Always navigate to transactions after import
      onNavigate('transactions');
    } catch(e) { toast('Import failed: ' + e.message); }
    finally { setLoading(false); }
  }

  // ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ Upload step ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€š